from six.moves import _thread as __thread
from eventlet.support import copy_globals

__patched__ = ["get_ident", "start_new_thread", "start_new", "allocate_lock", "allocate", "exit_thread", "exit", "interrupt_main", "LockType"]

copy_globals(__thread, globals(), names=__patched__, ignore_missing=True)

daemon_threads_allowed = getattr(__thread, "daemon_threads_allowed", lambda: True)
_count = getattr(__thread, "_count", lambda: 0)
_local = getattr(__thread, "_local", None)

